.card{position:relative;width:85.6mm;height:53.98mm;overflow:hidden;border:.25mm solid #94a3b8;border-radius:3mm;background:#fff;color:#0f172a;-webkit-print-color-adjust:exact;print-color-adjust:exact}
.card .top{position:absolute;inset:0 0 auto;height:11.5mm;display:flex;align-items:center;gap:2.6mm;padding:0 3.2mm;background:linear-gradient(120deg,#0b1220 0%,#111a33 45%,#1e3a8a 100%);color:#fff}
.card .logo{width:8mm;height:8mm;flex:none;border-radius:1.2mm;background:#fff;object-fit:contain;padding:.5mm}
.card .logo-fallback{display:flex;align-items:center;justify-content:center;width:8mm;height:8mm;flex:none;border-radius:1.2mm;background:rgba(255,255,255,.14);color:#c7d2fe;font-size:8.5pt;font-weight:800}
.card .top-text{min-width:0}
.card .school{font-size:8.6pt;font-weight:800;letter-spacing:.03em;line-height:1.05;text-transform:uppercase;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.card .school-full{margin-top:.5mm;font-size:5.8pt;font-weight:700;letter-spacing:.05em;line-height:1.1;text-transform:uppercase;color:#e0e7ff;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.card .subtitle{margin-top:.4mm;font-size:5.2pt;letter-spacing:.1em;line-height:1.1;text-transform:uppercase;color:#c7d2fe;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.card .accent{position:absolute;top:11.5mm;left:0;right:0;height:.9mm;background:linear-gradient(90deg,#4f46e5,#0ea5e9 55%,#10b981)}
.card .watermark{position:absolute;top:16.5mm;left:24mm;width:34mm;height:32mm;object-fit:contain;opacity:.06}
.card .photo{position:absolute;top:15mm;left:3mm;width:17mm;height:24mm;border:.25mm solid #cbd5e1;border-radius:1.5mm;object-fit:cover}
.card .photo-placeholder{position:absolute;top:15mm;left:3mm;width:17mm;height:24mm;border:.25mm dashed #94a3b8;border-radius:1.5mm;background:#f1f5f9;text-align:center;padding-top:9mm;font-size:6pt;color:#64748b}
.card .identity{position:absolute;top:14.6mm;left:22.5mm;width:38mm;height:29mm;overflow:hidden}
.card .name{max-height:10.5mm;overflow:hidden;font-weight:800;line-height:1.08;text-transform:uppercase;overflow-wrap:anywhere;word-break:break-word}
.card .name-normal{font-size:9pt}
.card .name-compact{font-size:7.4pt}
.card .name-very-compact{font-size:6.2pt}
.card .meta{margin-top:.9mm;font-size:5.9pt;line-height:1.18;color:#475569;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.card .meta b,.card .meta strong{color:#0f172a}
.card .qr{position:absolute;top:15mm;right:2.6mm;width:20.3mm;padding:.7mm;background:#fff;border:.2mm solid #e2e8f0;border-radius:1.2mm}
.card .qr svg{display:block;width:18.7mm!important;height:18.7mm!important}
.card .card-number{position:absolute;top:36.8mm;right:2.6mm;width:20.3mm;text-align:center;font:700 5.5pt/1.2 monospace;color:#1e3a8a}
.card .footer{position:absolute;right:3mm;bottom:2.3mm;left:3mm;display:flex;justify-content:space-between;border-top:.2mm solid #e2e8f0;padding-top:1.3mm;font-size:5.5pt;color:#64748b}
.card .footer b,.card .footer strong{color:#334155}
